INSERT INTO public.districts (id, division_id, slug, name, name_bn, description, image_url, lat, lng, popular_season) VALUES
  (1, 1, 'dhaka', 'Dhaka', 'ঢাকা', 'The vibrant 400-year-old historic capital city with Mughal heritage, bustling rivers, and street food culture.', 'https://images.unsplash.com/photo-1588714477688-cf28a50e94f7?w=800&auto=format&fit=crop&q=80', 23.8103, 90.4125, 'October to March'),
  (2, 1, 'gazipur', 'Gazipur', 'গাজীপুর', 'Home to the largest Safari Park in South Asia, serene eco-resorts, and dense Bhawal Sal forests.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=800&auto=format&fit=crop&q=80', 24.0023, 90.4267, 'Year round, especially Winter & Weekends'),
  (3, 1, 'narayanganj', 'Narayanganj', 'নারায়ণগঞ্জ', 'Ancient capital Panam City (Sonargaon), historic river forts, and the heritage of Jamdani weaving.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80', 23.6238, 90.5, 'November to February'),
  (4, 1, 'tangail', 'Tangail', 'টাঙ্গাইল', 'World-famous Tangail cotton & silk handloom sarees, Mohera Zamindar Bari, and legendary Porabari Chomchom.', 'https://images.unsplash.com/photo-1512436991641-6745cdb1723f?w=800&auto=format&fit=crop&q=80', 24.2513, 89.9167, 'October to March'),
  (5, 1, 'kishoreganj', 'Kishoreganj', 'কিশোরগঞ্জ', 'Spectacular Nikli Haor wetlands, all-weather submerged highway, and historic Isha Khan forts.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop&q=80', 24.4449, 90.7766, 'July to October (Haor season) & Winter'),
  (6, 1, 'manikganj', 'Manikganj', 'মানিকগঞ্জ', 'Famous for Baliati Palace (one of the largest zamindar palaces in Bangladesh) and Teota Zamindar Bari.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&auto=format&fit=crop&q=80', 23.8644, 90.0047, 'Autumn and Winter'),
  (7, 1, 'munshiganj', 'Munshiganj', 'মুন্সিগঞ্জ', 'Ancient Bikrampur heritage, Idrakpur water fort, Arial Beel wetlands, and Padma bridge views.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&auto=format&fit=crop&q=80', 23.5422, 90.5305, 'October to March'),
  (8, 1, 'narsingdi', 'Narsingdi', 'নরসিংদী', 'Ancient Wari-Bateshwar archaeological site dating back 2,500 years and the Dream Holiday Park.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&auto=format&fit=crop&q=80', 23.9322, 90.7154, 'Winter & Spring'),
  (9, 1, 'faridpur', 'Faridpur', 'ফরিদপুর', 'Spiritual city of Sufi Shah Farid, Jasimuddin’s ancestral home, and sweet Khejur Gur.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=800&auto=format&fit=crop&q=80', 23.6071, 89.8429, 'November to February'),
  (10, 1, 'gopalganj', 'Gopalganj', 'গোপালগঞ্জ', 'Birthplace and mausoleum complex of Bangabandhu Sheikh Mujibur Rahman in Tungipara.', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800&auto=format&fit=crop&q=80', 23.0051, 89.8266, 'Year round'),
  (11, 1, 'madaripur', 'Madaripur', 'মাদারীপুর', 'Padma riverbank viewpoints, historic Shah Madar shrine, and traditional molasses production.', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800&auto=format&fit=crop&q=80', 23.1641, 90.1897, 'Winter'),
  (12, 1, 'rajbari', 'Rajbari', 'রাজবাড়ী', 'Gateway to Southern Bangladesh along the mighty Padma River, historic railway heritage and Chamcham sweets.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80', 23.7574, 89.6445, 'October to February'),
  (13, 1, 'shariatpur', 'Shariatpur', 'শরীয়তপুর', 'Riverine beauty with the Padma and Meghna rivers confluence, named after Haji Shariatullah.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop&q=80', 23.2423, 90.4348, 'Winter & Autumn'),
  (14, 2, 'chattogram', 'Chattogram', 'চট্টগ্রাম', 'Commercial capital with Patenga Beach, Guliakhali green beach, heritage shrines, and Mezbani beef.', 'https://images.unsplash.com/photo-1588714477688-cf28a50e94f7?w=800&auto=format&fit=crop&q=80', 22.3569, 91.7832, 'October to March'),
  (15, 2, 'coxs-bazar', 'Cox''s Bazar', 'কক্সবাজার', 'The world’s longest natural unbroken sandy sea beach (120 km), Marine Drive, Inani, and Saint Martin coral island.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop&q=80', 21.4272, 92.0058, 'November to March'),
  (16, 2, 'rangamati', 'Rangamati (Sajek)', 'রাঙ্গামাটি (সাজেক ভ্যালি)', 'Valley of clouds Sajek, breathtaking Kaptai Lake, hanging bridges, and Chakma tribal lifestyle.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80', 22.6533, 92.1753, 'September to February'),
  (17, 2, 'bandarban', 'Bandarban', 'বান্দরবান', 'Highest mountain peaks of Bangladesh (Keokradong, Saka Haphong), Nafakhum waterfall, and Nilgiri hilltop.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&auto=format&fit=crop&q=80', 22.1953, 92.2184, 'October to March'),
  (18, 2, 'khagrachhari', 'Khagrachhari', 'খাগড়াছড়ি', 'Rich hill district with mysterious Alutila Cave, Richhang waterfall, and scenic mountain roads to Sajek.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&auto=format&fit=crop&q=80', 23.1192, 91.9846, 'October to March'),
  (19, 2, 'cumilla', 'Cumilla', 'কুমিল্লা', 'Ancient 8th-century Shalban Vihara (Mainamati), Lalmai Hills, and world-famous authentic Rasmalai.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=800&auto=format&fit=crop&q=80', 23.4682, 91.1788, 'November to February'),
  (20, 2, 'feni', 'Feni', 'ফেনী', 'Muhuri Project river barrage, scenic green embankment parks, and historic Bijoy Singh Dighi.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&auto=format&fit=crop&q=80', 23.0186, 91.3966, 'Winter & Autumn'),
  (21, 2, 'brahmanbaria', 'Brahmanbaria', 'ব্রাহ্মণবাড়িয়া', 'Cultural capital of classical music (Ustad Alauddin Khan), Titas river, and delicious Chhanar Mukhi.', 'https://images.unsplash.com/photo-1511497584788-87676104235f?w=800&auto=format&fit=crop&q=80', 23.9571, 91.1119, 'Winter'),
  (22, 2, 'noakhali', 'Noakhali', 'নোয়াখালী', 'Nijhum Dwip island (home to thousands of spotted deer), Gandhi Ashram, and Bay of Bengal coastline.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop&q=80', 22.8696, 91.0993, 'November to February'),
  (23, 2, 'chandpur', 'Chandpur', 'চাঁদপুর', 'City of Hilsa (Ilish) fish, iconic Padma-Meghna-Dakatia river triple estuary confluence (Mollahata).', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=800&auto=format&fit=crop&q=80', 23.2333, 90.6667, 'Monsoon for Hilsa & Winter for cruising'),
  (24, 2, 'lakshmipur', 'Lakshmipur', 'লক্ষ্মীপুর', 'Meghna riverbanks, Char Alexander eco-tourism, Dalal Bazar Zamindar Bari, and betel nut orchards.', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800&auto=format&fit=crop&q=80', 22.9425, 90.8412, 'Winter'),
  (25, 3, 'sylhet', 'Sylhet', 'সিলেট', 'Land of two leaves and a bud, spiritual Hazrat Shah Jalal shrine, crystal-clear Jaflong rivers, and Ratargul swamp forest.', 'https://images.unsplash.com/photo-1596895111956-bf1cf0599ce5?w=800&auto=format&fit=crop&q=80', 24.8949, 91.8687, 'October to March (Monsoon for waterfalls)'),
  (26, 3, 'moulvibazar', 'Moulvibazar (Sreemangal)', 'মৌলভীবাজার (শ্রীমঙ্গল)', 'The tea capital of Bangladesh with rolling tea estates, Lawachara rainforest, Madhabkunda waterfall, and 7-layer tea.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=800&auto=format&fit=crop&q=80', 24.3065, 91.7296, 'Year round, especially Winter'),
  (27, 3, 'sunamganj', 'Sunamganj (Tanguar Haor)', 'সুনামগঞ্জ (টাঙ্গুয়ার হাওর)', 'Ramsar site Tanguar Haor, luxury houseboats, Shimul Bagan (red silk cotton forest), and Jadukata River.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80', 25.0658, 91.4073, 'July to October (Houseboat season) & Winter for birds'),
  (28, 3, 'habiganj', 'Habiganj', 'হবিগঞ্জ', 'Satchari National Park, lush green tea gardens of Chunarughat, and serene Baniachong (Asia’s largest village).', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800&auto=format&fit=crop&q=80', 24.3749, 91.4155, 'October to February'),
  (29, 4, 'rajshahi', 'Rajshahi', 'রাজশাহী', 'Silk City along the Padma River, renowned for delicious Fazli mangoes, Varendra Research Museum, and Kalai Ruti.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=800&auto=format&fit=crop&q=80', 24.3745, 88.6042, 'May-July for Mangoes / Nov-Feb for Travel'),
  (30, 4, 'bogura', 'Bogura', 'বগুড়া', 'Ancient 3rd-century BC Mahasthangarh fortress city, rich history, and world-famous Bogurar Doi (curd).', 'https://images.unsplash.com/photo-1512436991641-6745cdb1723f?w=800&auto=format&fit=crop&q=80', 24.8465, 89.3777, 'October to March'),
  (31, 4, 'naogaon', 'Naogaon', 'নওগাঁ', 'UNESCO World Heritage site Somapura Mahavihara (Paharpur Buddhist Monastery), Kusumba Mosque, and Dubalhati Palace.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&auto=format&fit=crop&q=80', 24.8103, 88.9419, 'November to February'),
  (32, 4, 'natore', 'Natore', 'নাটোর', 'Historic palace of Rani Bhabani (Natore Rajbari), Uttara Ganabhaban, and mouth-watering Kachagolla sweet.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=800&auto=format&fit=crop&q=80', 24.4206, 88.9324, 'October to March'),
  (33, 4, 'chapainawabganj', 'Chapainawabganj', 'চাঁপাইনবাবগঞ্জ', 'Mango capital of Bangladesh, historic Choto Sona Mosque (1493 AD), and Gambhira folk music heritage.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&auto=format&fit=crop&q=80', 24.5965, 88.2775, 'Summer for Mangoes / Winter for Heritage'),
  (34, 4, 'pabna', 'Pabna', 'পাবনা', 'Hardinge Bridge & Lalon Shah Bridge over the Padma, historic Tarash Rajbari, and Anukulchandra Satsanga Ashram.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80', 24.0064, 89.2372, 'October to February'),
  (35, 4, 'sirajganj', 'Sirajganj', 'সিরাজগঞ্জ', 'Iconic Bangabandhu Jamuna Multipurpose Bridge, Navaratna Temple in Hatkumrul, and handloom lungi/sarees.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&auto=format&fit=crop&q=80', 24.4534, 89.7008, 'Autumn and Winter'),
  (36, 4, 'joypurhat', 'Joypurhat', 'জয়পুরহাট', 'Archaeological sites like Lokma Rajbari, Paharpur adjacent trails, and sugar mills belt.', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800&auto=format&fit=crop&q=80', 25.1015, 89.0277, 'Winter'),
  (37, 5, 'khulna', 'Khulna (Sundarbans)', 'খুলনা (সুন্দরবন)', 'Gateway to UNESCO World Heritage Sundarbans (largest mangrove forest on Earth & Royal Bengal Tiger habitat) and spicy Chui Jhal beef.', 'https://images.unsplash.com/photo-1511497584788-87676104235f?w=800&auto=format&fit=crop&q=80', 22.8456, 89.5403, 'November to March (Cruising Season)'),
  (38, 5, 'bagerhat', 'Bagerhat', 'বাগেরহাট', 'UNESCO World Heritage Historic Mosque City of Bagerhat featuring the 15th-century Sixty Dome Mosque (Shat Gombuj Masjid).', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=800&auto=format&fit=crop&q=80', 22.6516, 89.7859, 'October to February'),
  (39, 5, 'jashore', 'Jashore', 'যশোর', 'Gadkhali flower capital (blooming roses & gerberas), poet Michael Madhusudan Dutt’s birthplace, and date palm jaggery (Patali Gur).', 'https://images.unsplash.com/photo-1512436991641-6745cdb1723f?w=800&auto=format&fit=crop&q=80', 23.1664, 89.2182, 'December to February (Flower season & Winter)'),
  (40, 5, 'satkhira', 'Satkhira', 'সাতক্ষীরা', 'Sundarbans Western range (Munshiganj & Kalidaspur eco-resorts), wild honey harvest, and fresh Sundarbans crabs.', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800&auto=format&fit=crop&q=80', 22.7185, 89.0705, 'November to March'),
  (41, 5, 'kushtia', 'Kushtia', 'কুষ্টিয়া', 'Mystical shrine of Baul philosopher Fakir Lalon Shah (Chheuriya), Rabindranath Tagore’s Kuthibari in Shilaidaha, and Gorai river.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80', 23.9013, 89.1204, 'Dol Purnima (March) & Autumn/Winter'),
  (42, 5, 'meherpur', 'Meherpur', 'মেহেরপুর', 'Mujibnagar Memorial Complex where the Provisional Government of Bangladesh took oath in 1971.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&auto=format&fit=crop&q=80', 23.7719, 88.6318, 'Year round'),
  (43, 5, 'chuadanga', 'Chuadanga', 'চুয়াডাঙ্গা', 'Historic Gholdari Mosque, Carew & Co. (British era sugar distillery heritage), and Mathabhanga river.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=800&auto=format&fit=crop&q=80', 23.6402, 88.8418, 'Winter'),
  (44, 5, 'jhenaidah', 'Jhenaidah', 'ঝিনাইদহ', 'Famous for Marjat Baor eco-tourism, Naldanga Rajbari temple complex, and sweet banana cultivation.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&auto=format&fit=crop&q=80', 23.545, 89.1726, 'Winter & Spring'),
  (45, 5, 'magura', 'Magura', 'মাগুরা', 'Historic Siddheswari Math, Gorai river viewpoints, and traditional Katayani Puja festival celebrations.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&auto=format&fit=crop&q=80', 23.4873, 89.4198, 'Autumn and Winter'),
  (46, 5, 'narail', 'Narail', 'নড়াইল', 'Land of legendary painter SM Sultan (Shishu Swargo art complex), Chitra River, and traditional otter fishing.', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800&auto=format&fit=crop&q=80', 23.1725, 89.5127, 'Autumn and Winter'),
  (47, 6, 'barishal', 'Barishal', 'বরিশাল', 'The Venice of Bengal with romantic backwaters, floating guava markets, Guthia Mosque, and luxury river launches.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop&q=80', 22.701, 90.3535, 'July to October for Guava Markets / Nov-Feb for Cruising'),
  (48, 6, 'patuakhali', 'Patuakhali (Kuakata)', 'পটুয়াখালী (কুয়াকাটা)', 'Daughter of the Sea (Sagor Konna) Kuakata beach where both sunrise and sunset can be viewed over the Bay of Bengal.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop&q=80', 21.8167, 90.1167, 'October to March'),
  (49, 6, 'bhola', 'Bhola', 'ভোলা', 'The largest island district of Bangladesh, Char Kukri Mukri wildlife sanctuary, mangrove forests, and buffalo milk curd.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&auto=format&fit=crop&q=80', 22.6859, 90.6481, 'November to February'),
  (50, 6, 'jhalokathi', 'Jhalokathi', 'ঝালকাঠি', 'Famous for Bhimruli floating guava and hog plum (Amra) market canals, water hyacinth trails, and Sujabad fort.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&auto=format&fit=crop&q=80', 22.6406, 90.1987, 'July to September (Guava canal boats)'),
  (51, 6, 'pirojpur', 'Pirojpur', 'পিরোজপুর', 'Kuriana floating market, Baleshwar riverbank, and Swarupkathi timber & coconut trading canals.', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800&auto=format&fit=crop&q=80', 22.5841, 89.972, 'Monsoon and Winter'),
  (52, 6, 'barguna', 'Barguna', 'বরগুনা', 'Shuvo Shondha sea beach, Haringhata eco-tourism mangrove trail, and scenic Payra river delta.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80', 22.0953, 90.1121, 'November to March'),
  (53, 7, 'rangpur', 'Rangpur', 'রংপুর', 'Palatial Tajhat Palace (now archaeological museum), Chikli Water Park, and delicious Haribhanga mangoes.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=800&auto=format&fit=crop&q=80', 25.7439, 89.2752, 'October to February / June for Haribhanga'),
  (54, 7, 'dinajpur', 'Dinajpur', 'দিনাজপুর', 'Masterpiece 18th-century terracotta Kantajew Temple (Kantaji Mandir), Ramsagar National Park, and aromatic Kataribhog rice.', 'https://images.unsplash.com/photo-1512436991641-6745cdb1723f?w=800&auto=format&fit=crop&q=80', 25.6217, 88.6355, 'October to March'),
  (55, 7, 'panchagarh', 'Panchagarh (Tetulia)', 'পঞ্চগড় (তেঁতুলিয়া)', 'Northernmost tip of Bangladesh with plainland tea gardens, views of Mt. Kanchenjunga (Himalayas) in autumn, and Mahananda river.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&auto=format&fit=crop&q=80', 26.3354, 88.5517, 'October to December (Kanchenjunga clear views)'),
  (56, 7, 'nilphamari', 'Nilphamari', 'নীলফামারী', 'Historic Nil Sagar lake (sanctuary for migratory birds), Saidpur railway workshop heritage, and Teesta Barrage.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=800&auto=format&fit=crop&q=80', 25.9318, 88.856, 'November to February'),
  (57, 7, 'lalmonirhat', 'Lalmonirhat', 'লালমনিরহাট', 'Teesta Barrage, Mogolhat border crossing, and Tin Bigha Corridor enclave heritage.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=800&auto=format&fit=crop&q=80', 25.9923, 89.2847, 'Winter'),
  (58, 7, 'kurigram', 'Kurigram', 'কুড়িগ্রাম', 'Brahmaputra and Dharla river islands (Chars), historic Chilmari river port, and Chandamari Mosque.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&auto=format&fit=crop&q=80', 25.8054, 89.6362, 'Autumn and Winter'),
  (59, 7, 'gaibandha', 'Gaibandha', 'গাইবান্ধা', 'Brahmaputra river eco-tourism, Balashi Ghat river views, and legendary Rasmanjari sweets.', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800&auto=format&fit=crop&q=80', 25.3288, 89.5406, 'Winter'),
  (60, 7, 'thakurgaon', 'Thakurgaon', 'ঠাকুরগাঁও', 'Ancient King’s Palace in Baliadangi, century-old giant mango tree (Shurjapuri), and Tangon river.', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800&auto=format&fit=crop&q=80', 26.0337, 88.4617, 'Autumn and Winter'),
  (61, 8, 'mymensingh', 'Mymensingh', 'ময়মনসিংহ', 'Shashi Lodge (Rajbari), scenic Brahmaputra riverbanks, Bangladesh Agricultural University botanical gardens, and Muktagacha Monda sweet.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?w=800&auto=format&fit=crop&q=80', 24.7471, 90.4203, 'Autumn and Winter'),
  (62, 8, 'netrokona', 'Netrokona (Birishiri)', 'নেত্রকোণা (বিরিশিরি)', 'Mesmerizing white ceramic clay hills of Durgapur, turquoise blue Someshwari River lake, and Hajong/Garo tribal culture.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80', 24.8833, 90.7333, 'October to March (Clear water season)'),
  (63, 8, 'jamalpur', 'Jamalpur', 'জামালপুর', 'Famous for traditional Nakshi Kantha handcrafted quilts, Lojpoti sweet curd, and historic Gakul Amin Dargah.', 'https://images.unsplash.com/photo-1512436991641-6745cdb1723f?w=800&auto=format&fit=crop&q=80', 24.9375, 89.9378, 'Winter'),
  (64, 8, 'sherpur', 'Sherpur (Garo Hills)', 'শেরপুর (গারো পাহাড়)', 'Ghazni Abakash and Madhutila eco-parks in the foothills of Meghalaya Garo mountain ranges.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&auto=format&fit=crop&q=80', 25.0205, 90.0153, 'October to February')
